import { Vector3, type Object3D } from 'three';
import type { SiteHotspotConfig, SiteModelConfig } from '../../config/schema';
import { loadModelSource, type LoadModelOptions } from '../devices/deviceModel';
import { getObjectsBounds } from '../devices/partBindings';

/**
 * 场地热点：场地模型里的一台设备。
 * `objects` 是命中的模型节点（可能为空——只给了 `position` 的时候），
 * `anchor` 是标记在世界坐标里的落点（节点包围盒中心 + offset）。
 */
export interface SiteHotspotRuntime {
  config: SiteHotspotConfig;
  objects: Object3D[];
  anchor: Vector3;
}

export interface SiteModelIssue {
  hotspotId: string;
  nodeName: string;
}

export interface LoadedSiteModel {
  root: Object3D;
  hotspots: SiteHotspotRuntime[];
  issues: SiteModelIssue[];
}

/**
 * 场地模型里一台设备通常由几十个节点组成，建模方给的前缀也可能只是设备名的一部分，
 * 因此名称匹配按「完全相同或以该名称开头」处理（`2250kV工频实验变压器` 能命中
 * `2250kV工频实验变压器0034`）。
 */
export function matchesNodeName(objectName: string, nodeName: string) {
  return objectName === nodeName || objectName.startsWith(nodeName);
}

export function resolveSiteHotspots(root: Object3D, hotspots: SiteHotspotConfig[]) {
  const issues: SiteModelIssue[] = [];
  const resolved: SiteHotspotRuntime[] = [];
  const nodes: Object3D[] = [];
  root.traverse(object => { if (object.name) nodes.push(object); });

  for (const config of hotspots) {
    const objects = config.nodeNames.length
      ? nodes.filter(object => config.nodeNames.some(nodeName => matchesNodeName(object.name, nodeName)))
      : [];
    if (config.nodeNames.length && objects.length === 0) {
      for (const nodeName of config.nodeNames) issues.push({ hotspotId: config.id, nodeName });
    }
    const bounds = objects.length ? getObjectsBounds(objects) : null;
    const anchor = bounds
      ? bounds.getCenter(new Vector3())
      : config.position
        ? new Vector3().fromArray(config.position)
        : new Vector3();
    anchor.add(new Vector3().fromArray(config.offset));
    resolved.push({ config, objects, anchor });
  }
  return { hotspots: resolved, issues };
}

/** 点中的模型节点属于哪个热点（自身或任一祖先节点名命中即可）。 */
export function findHotspotId(object: Object3D, root: Object3D, hotspots: readonly SiteHotspotRuntime[]): string | null {
  let current: Object3D | null = object;
  while (current) {
    if (current.name) {
      const hit = hotspots.find(hotspot =>
        hotspot.config.nodeNames.some(nodeName => matchesNodeName(current!.name, nodeName)));
      if (hit) return hit.config.id;
    }
    if (current === root) break;
    current = current.parent;
  }
  return null;
}

export async function loadSiteModel(site: SiteModelConfig, options: LoadModelOptions = {}): Promise<LoadedSiteModel> {
  const root = await loadModelSource(site.source, options);
  const { hotspots, issues } = resolveSiteHotspots(root, site.hotspots);
  return { root, hotspots, issues };
}
