import type { PlacementConfig } from '../../config/schema';

/** 三维院区的模型变换（场景原点即 `placement.anchor`，所以位置只有高度分量）。 */
export interface PlacementTransform {
  position: [number, number, number];
  /** three.js 的 Y 轴旋转（弧度）。 */
  rotationY: number;
  scale: number;
}

/**
 * 坐标约定（与 `shared/geo.ts` 的 `sceneFromEnu` 一致）：
 * 场景 `+X = 东`、`-Z = 北`、`+Y = 上`，原点 = `placement.anchor`，单位米。
 *
 * `headingDeg` 是「模型 -Z 轴相对真北的顺时针夹角」：
 * - heading = 0 ⇒ 模型的 -Z 正对真北，也就是场景的 -Z，不用转；
 * - heading = h ⇒ 模型的 -Z 要指向罗盘方位 h，即世界方向 `(sin h, 0, -cos h)`。
 *   three.js 绕 Y 轴转 θ 会把局部 `(0, 0, -1)` 映射到 `(-sin θ, 0, -cos θ)`；
 *   两者相等要求 `θ = -h`。**所以这里是负号**，别写成 `+headingDeg`。
 */
export function placementTransform(placement: PlacementConfig): PlacementTransform {
  return {
    position: [0, placement.elevationM, 0],
    rotationY: -(placement.headingDeg * Math.PI) / 180,
    scale: placement.scale,
  };
}
